import random
from collections import deque

def bfs_girth(adj, n, max_girth=6):
    for s in range(n):
        dist = [-1] * n
        dist[s] = 0
        q = deque([s])
        parent = [-1] * n
        while q:
            u = q.popleft()
            if dist[u] > max_girth // 2 + 1:
                break
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                elif v != parent[u]:
                    if dist[u] + dist[v] + 1 < max_girth:
                        return False
    return True

def random_regular_graph(n, d, max_attempts=500):
    for attempt in range(max_attempts):
        adj = [[] for _ in range(n)]
        for u in range(n):
            while len(adj[u]) < d:
                v = random.randint(0, n-1)
                if v != u and v not in adj[u] and len(adj[v]) < d and u not in adj[v]:
                    adj[u].append(v)
                    adj[v].append(u)
        if all(len(adj[i]) == d for i in range(n)):
            if bfs_girth(adj, n, 6):
                edges = []
                for u in range(n):
                    for v in adj[u]:
                        if u < v:
                            edges.append((u, v))
                return sorted(edges)
    return None

